effect.shader:
const int N = 9;
const float OFF[9] = float[9](-4.0, -3.0, -2.0, -1.0, 0.0, 1.0, 2.0, 3.0, 4.0);
const float WT[9]  = float[9](0.028, 0.065, 0.121, 0.175, 0.198, 0.175, 0.121, 0.065, 0.028);
const vec3  LUMA   = vec3(0.2126, 0.7152, 0.0722);

void main() {
    vec4 original = texture(inputImg, acScreenNorm);
    if (radius <= 0.0) { fragColor = original; return; }

    vec2 direction = (acPass == 0) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec2 passo = direction * acTexelSize * (radius * acEscalaDePixel);

    vec4 soma = vec4(0.0);
    for (int i = 0; i < N; i++) {
        vec2 uv = acScreenNorm + passo * OFF[i];
        vec4 c;
        if (acPass == 0) {
            c = texture(inputImg, uv);
            float luz = dot(c.rgb, LUMA);
            float corte = smoothstep(threshold, threshold + 0.2, luz);
            c.rgb *= mix(softness, 1.0, corte);
        } else {
            c = texture(hblur, uv);
        }
        soma += c * WT[i];
    }

    if (acPass == 0) {
        fragColor = soma;
    } else {
        vec3 glow = soma.rgb * strength;
        fragColor = vec4(original.rgb + glow * original.a, original.a);
    }
}
